import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"特殊寄存器访问","link":"/api/SIMD-API/c_api/spr/spr"},{"text":"asc_get_saturation_flag","link":"/api/SIMD-API/c_api/spr/asc_get_saturation_flag"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/spr/asc_get_saturation_flag.md","filePath":"api/SIMD-API/c_api/spr/asc_get_saturation_flag.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788435672000}'),t={name:"api/SIMD-API/c_api/spr/asc_get_saturation_flag.md"};function c(e,s,i,_,r,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>asc_get_saturation_flag</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/spr/spr.h&quot;</code>。</p><p>按饱和模式类型读取当前是否开启饱和，并返回布尔类型的结果。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">asc_get_saturation_flag</span><span class="p">(</span><span class="n">asc_saturation_mode</span><span class="w"> </span><span class="n">saturation_mode</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">saturation_mode</td><td align="left">输入</td><td align="left">饱和模式类型，取值见<a href="../defs/enum/asc_saturation_mode.html">asc_saturation_mode</a>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p><code>true</code>表示当前该模式下饱和已开启；<code>false</code>表示未开启（对INT为截断；对FLOAT/FLOAT8/CAST为非饱和或截断）。</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>返回值是API语义层结果：<code>true</code>表示该模式下饱和已开启，<code>false</code>表示未开启（对INT为截断；对FLOAT/FLOAT8/CAST为非饱和或截断）。各模式语义差异见<a href="asc_set_saturation_flag.html">asc_set_saturation_flag</a>表1。</li><li>对<code>CAST</code>模式，即使本接口返回<code>true</code>，也需同时满足饱和策略为<code>USE_GLOBAL</code>，CAST饱和配置才会在精度转换中真正生效。详见<a href="asc_set_saturation_strategy.html">asc_set_saturation_strategy</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>场景：动态量化场景，溢出需饱和到±MAX而非截断。须先将策略设为<code>USE_GLOBAL</code>并开启CAST饱和。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// SIMD_VF外：asc_get_saturation_flag查询当前CAST饱和开关</span>
<span class="kt">bool</span><span class="w"> </span><span class="n">cast_sat_enabled</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_get_saturation_flag</span><span class="p">(</span><span class="n">asc_saturation_mode</span><span class="o">::</span><span class="n">CAST</span><span class="p">);</span>
<span class="n">asc_override_strategy</span><span class="w"> </span><span class="n">old_strategy</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_get_saturation_strategy</span><span class="p">();</span>

<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="o">!</span><span class="n">cast_sat_enabled</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">asc_set_saturation_strategy</span><span class="p">(</span><span class="n">asc_override_strategy</span><span class="o">::</span><span class="n">USE_GLOBAL</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_set_saturation_flag</span><span class="p">(</span><span class="n">asc_saturation_mode</span><span class="o">::</span><span class="n">CAST</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">);</span>
<span class="p">}</span>

<span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">act_ub</span><span class="p">,</span><span class="w"> </span><span class="n">act_gm</span><span class="p">,</span><span class="w"> </span><span class="n">act_burst_bytes</span><span class="p">);</span>
<span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">bias_ub</span><span class="p">,</span><span class="w"> </span><span class="n">bias_gm</span><span class="p">,</span><span class="w"> </span><span class="n">bias_burst_bytes</span><span class="p">);</span>
<span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>

<span class="c1">// 矢量计算循环内：激活+bias加法后float→int32（全局CAST饱和生效）</span>

<span class="c1">// SIMD_VF外：若本段临时开启过CAST饱和，则恢复进入本段前的配置</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="o">!</span><span class="n">cast_sat_enabled</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">asc_set_saturation_flag</span><span class="p">(</span><span class="n">asc_saturation_mode</span><span class="o">::</span><span class="n">CAST</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_set_saturation_strategy</span><span class="p">(</span><span class="n">old_strategy</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>数据搬运与Reg cast模式可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/02_simd_c_api/03_c_api/02_reg_vector_compute/cast">Cast样例</a>。</p></article></div>`,1)])])}const u=a(t,[["render",c]]);export{h as __pageData,u as default};
